package geo

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"sync"
)

// Cartographic Census boundaries, generated by tools/census_states.py. These
// exclude areas outside the chosen state rather than just clipping its box.
//
//go:embed state-masks.json.gz
var maskData []byte
var maskOnce sync.Once
var maskShapes map[string][][][2]float64
var maskError error

type Mask struct {
	codes []string
	rows  map[float64][][2]float64
}

func NewMask(name string) (*Mask, error) {
	if name == "" {
		return nil, nil
	}
	maskOnce.Do(func() {
		r, e := gzip.NewReader(bytes.NewReader(maskData))
		if e != nil {
			maskError = e
			return
		}
		defer r.Close()
		maskError = json.NewDecoder(r).Decode(&maskShapes)
	})
	if maskError != nil {
		return nil, maskError
	}
	m := &Mask{rows: map[float64][][2]float64{}}
	for _, state := range States() {
		if name == "CONUS" || strings.EqualFold(name, state.Code) || strings.EqualFold(name, state.Name) {
			m.codes = append(m.codes, state.Code)
		}
	}
	if len(m.codes) == 0 {
		return nil, fmt.Errorf("unknown region mask %q", name)
	}
	return m, nil
}

// Contains caches horizontal scanline intersections. A large lattice has many
// points on each latitude, so polygon work is paid once per row, not per point.
// Access one Mask from a single goroutine.
func (m *Mask) Contains(lat, lon float64) bool {
	if m == nil {
		return true
	}
	intervals, ok := m.rows[lat]
	if !ok {
		for _, code := range m.codes {
			var crosses []float64
			for _, ring := range maskShapes[code] {
				for i := 1; i < len(ring); i++ {
					a, b := ring[i-1], ring[i]
					if (a[1] > lat) != (b[1] > lat) {
						crosses = append(crosses, a[0]+(b[0]-a[0])*(lat-a[1])/(b[1]-a[1]))
					}
				}
			}
			sort.Float64s(crosses)
			for i := 0; i+1 < len(crosses); i += 2 {
				intervals = append(intervals, [2]float64{crosses[i], crosses[i+1]})
			}
		}
		sort.Slice(intervals, func(i, j int) bool { return intervals[i][0] < intervals[j][0] })
		merged := [][2]float64{}
		for _, p := range intervals {
			if len(merged) > 0 && p[0] <= merged[len(merged)-1][1]+1e-9 {
				merged[len(merged)-1][1] = max(merged[len(merged)-1][1], p[1])
			} else {
				merged = append(merged, p)
			}
		}
		intervals = merged
		m.rows[lat] = intervals
	}
	i := sort.Search(len(intervals), func(i int) bool { return intervals[i][1] >= lon })
	return i < len(intervals) && intervals[i][0] <= lon
}
